effect.shader:
#define PI 3.14159265359
float getVal(vec4 col, int prop) {
if (prop == 1) return col.r;
if (prop == 2) return col.g;
if (prop == 3) return col.b;
if (prop == 4) return col.a;
return dot(col.rgb, vec3(0.299, 0.587, 0.114));
}
void main() {
vec2 uv = acScreenNorm;
float soft = max(softness, 1.0) * 0.001;
vec4 s_left  = texture2DCv(bumpMap.texture, uv + vec2(-soft, 0.0));
vec4 s_right = texture2DCv(bumpMap.texture, uv + vec2(soft, 0.0));
vec4 s_up    = texture2DCv(bumpMap.texture, uv + vec2(0.0, soft));
vec4 s_down  = texture2DCv(bumpMap.texture, uv + vec2(0.0, -soft));
float v_l = getVal(s_left, int(property));
float v_r = getVal(s_right, int(property));
float v_u = getVal(s_up, int(property));
float v_d = getVal(s_down, int(property));
float h_scale = height * 0.1;
vec3 normal = normalize(vec3(v_l - v_r, v_d - v_u, 1.0 / h_scale));
vec2 refractOff = normal.xy * (displacement * 0.01);
vec4 src = texture2DCv(inputImg.texture, uv + refractOff);
vec3 l_dir;
if (lightType == 0) {
float rad = (lightDirection - 90.0) * (PI / 180.0);
float h_rad = (lightHeight * 0.9) * (PI / 180.0);
l_dir = normalize(vec3(cos(rad) * cos(h_rad), sin(rad) * cos(h_rad), sin(h_rad)));
} else {
l_dir = normalize(vec3(lightPosition - uv, lightHeight * 0.01));
}
vec3 viewDir = vec3(0.0, 0.0, 1.0);
vec3 halfDir = normalize(l_dir + viewDir);
float diff = max(dot(normal, l_dir), 0.0);
float spec = pow(max(dot(normal, halfDir), 0.0), 1.0 / max(roughness, 0.001));
vec3 ambCol = src.rgb * (ambient * 0.01);
vec3 diffCol = src.rgb * diff * (diffuse * 0.01) * lightColor.rgb * (lightIntensity * 0.01);
vec3 specBase = lightColor.rgb * spec * (specular * 0.01) * (lightIntensity * 0.01);
vec3 specCol = mix(specBase, specBase * src.rgb, metal * 0.01);
vec3 finalCol = ambCol + diffCol + specCol;
gl_FragColor = vec4(finalCol, src.a);
}
